void compress_string(const char *src, char *dest)
{
    const char *p = src;
    int count;
    char prev;

    if (!src) {
        *dest = '\0';
        return;
    }

    while (*p) {
        prev = *p;
        count = 0;
        while (*p && *p == prev) {
            count++;
            p++;
        }
        dest[0] = prev;
        dest += 1 + snprintf(dest + 1, 16, "%d", count);
    }
    *dest = '\0';
}

